import{_ as s,c as a,a as r,b as l,d as n,w as e,r as g,o as i,e as o}from"./app-2_02a9Gj.js";const h={},d={class:"table-of-contents"};function u(f,p){const t=g("router-link");return i(),a("div",null,[p[11]||(p[11]=r("h1",{id:"вопросы-и-ответы-о-марксе-и-марксизме",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#вопросы-и-ответы-о-марксе-и-марксизме"},[r("span",null,"Вопросы и ответы: О Марксе и марксизме")])],-1)),p[12]||(p[12]=r("p",null,"Шелике Вальтраут Фрицевна. Май 2010. Актуализировано 23 сентября 2010.",-1)),r("nav",d,[r("ul",null,[r("li",null,[n(t,{to:"#предисловие"},{default:e(()=>[...p[0]||(p[0]=[o("Предисловие",-1)])]),_:1})]),r("li",null,[n(t,{to:"#про-отчуждение"},{default:e(()=>[...p[1]||(p[1]=[o("Про отчуждение",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-моеи-научнои-судьбе-о-диамате-и-истмате-о-марксизме"},{default:e(()=>[...p[2]||(p[2]=[o("О моей научной судьбе, о диамате и истмате, о марксизме",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-марксизме-и-позитивизме"},{default:e(()=>[...p[3]||(p[3]=[o("О марксизме и позитивизме",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-вульгаризации-взглядов-маркса"},{default:e(()=>[...p[4]||(p[4]=[o("О вульгаризации взглядов Маркса",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-типологии-революции"},{default:e(()=>[...p[5]||(p[5]=[o("О типологии революций",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-критериях-прогресса"},{default:e(()=>[...p[6]||(p[6]=[o("О критериях прогресса",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-классах-о-социальных-и-общественных-отношениях"},{default:e(()=>[...p[7]||(p[7]=[o("О классах, о социальных и общественных отношениях",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-научности-истории"},{default:e(()=>[...p[8]||(p[8]=[o("О научности истории",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-капитализме-и-об-отчужденном-характере-труда"},{default:e(()=>[...p[9]||(p[9]=[o("О капитализме и об отчужденном характере труда",-1)])]),_:1})]),r("li",null,[n(t,{to:"#о-разном"},{default:e(()=>[...p[10]||(p[10]=[o("О разном",-1)])]),_:1})])])]),p[13]||(p[13]=l('<h2 id="предисловие" tabindex="-1"><a class="header-anchor" href="#предисловие"><span>Предисловие</span></a></h2><p>Весной 2010 года в <a href="http://www.diary.ru/~vive-liberta/" target="_blank" rel="noopener noreferrer">интернетовском сообществе «Liberta»</a> развернулась дискуссия о роли марксизма в советской историографии Великой Французской буржуазной революции ХYIII века. Слово за словом, и участники дискуссии поставили перед собой вопрос «А что такое марксизм?» и стали искать ответ.</p><p>«Синяя блуза» напоролся на мой сайт <a href="http://www.wtschaelike.ru//" target="_blank" rel="noopener noreferrer">www.wtschaelike.ru</a> «Мой Маркс» и порекомендовал его членам сообщества. «Форстер 2005» выложила в интернете свой давний студенческий конспект идей Маркса о законах истории, сделанный по моим работам, добавив, что «когда-то, в универе, изучая диаматовскую философию, с большим интересом читала статьи Вальтраут Шелике и конспектировала. Вспомнила о них и стала искать по сети в связи с нашим спором».</p><p>Обо всем этом мне просигналила поисковая система Google, и я заглянула на сайт либертатов. Среди обсуждаемых вопросах о марксизме я обнаружила там обсуждение также и проблемы отчуждения по Марксу. Написала в письме, что я по этому поводу думаю.</p><p>«Форстер 2005» с моего разрешения выложила это письмо на своей странице в сайте. От себя «Forster 2005» добавила:</p><p>«Было бы замечательно, если бы Вальтраут „вживую“ к нашему разговору присоединилась, если такая возможность есть. По крайней мере, у меня к ней вопросов много. Может отдельную тему завести, как раз завтра день рождения Маркса?»</p><p>В итоге на сайте «Liberta» завели раздел «О Марксе» и я стала отвечать на вопросы... Так возникли <a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Вопросы и ответы: О Марксе и марксизме</a>.</p><h2 id="про-отчуждение" tabindex="-1"><a class="header-anchor" href="#про-отчуждение"><span>Про отчуждение</span></a></h2><p>2010-05-04 в 21:37</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p94081604.htm" target="_blank" rel="noopener noreferrer">Forster2005</a>. С разрешения В. Шелике цитирую ее письмо (адресовано было Натали, но и всем нам):</strong></p><p><strong>В. Шелике.</strong> Интересна реакция участников дискуссии на положение о необходимости снятия отчуждения переходом человечества к коммунизму. Но тут спорящие делают типичную, распространенную ошибку, путая Марксово Aeusserung (делание внешним, овнешнение) и Endfremdung (отчуждение). При переводе работ Маркса на русский оба понятия часто переводятся просто как отчуждение, отсюда неверное понимание позиции Маркса. У Маркса Aeusserung (делание внешним, овнешнение) существует в деятельности людей на всем протяжении истории и ему противостоит Aneignung (делание своим собственным, присвоение, овнутрение), что инстинктивно уловила часть участников дискуссии. А вот второе (Entfremdung) в деятельности людей и есть именно отчуждение (делание чужым, чуждым и даже враждебным, стоящим над человеком)и оно характерно только для определенного периода истории. Отчуждение (Entfremdung) делает жизнь человека (человечества) обесчеловеченной (entmenschlich). Против обесчеловеченной жизни индивиды и протестуют в социальной революции (по Марксу).</p><p>Я в своих лекциях и на семинарах всегда просила студентов подумать над тем, что же не устраивало в жизни накануне революции разных людей из самых различных социальных слоев. Такое начало исходно освобождает ход мысли от грубого экономического детерминизма, приписываемого Марксу (но Марксу не свойственного), и исходно дает картину целого комплекса противоречий того состояния жизни людей в Англии или Франции, которое осознавалось людьми на чувственном или идеологическом уровне, и толкавший живых людей (с их потребностями и их идеалами жизни) к революции и к контрреволюции. И этот «хаос» недовольства, идей и мечтаний можно затем обосновать (найти его истоки) в экономической, социальной, политической, духовной жизни людей того предреволюционного времени. Маркс, конечно, не отрицал роль идей в жизни людей, он «только» искал и находил еще и источники самих идей, при том не просто в головах людей, а в самой жизни людей (экономической, социальной, политической, духовной), Эти причины, источники, (экономические, социальные, политические, духовные) революционных и контрреволюционных идей существуют в жизни людей независимо от того, насколько они действительно (адекватно) были осознаны людьми, т. е. они существуют материально (и не только в экономике). Накануне революции противоречия материальной жизни (т. е. той жизни, которой люди действительно живут независимо от того, понимают, осознают они ее или не понимают и не осознают), дошли до такой степени обесчеловечивания жизни, что становятся и воспринимаются как невыносимые (по разному разными людьми), ибо ставят под угрозу существование и развитие живых индивидов. Вот тогда и созревает социальная революция как протест индивидов против обесчеловеченной жизни (Маркс).</p><p>А уж после этого можно углубиться в совокупность конкретных экономических, социальных, политических и духовных противоречий жизни того времени, обнаруживая и вскрывая здесь материальные источники грядущей революции, рассмотреть объективную расстановку классовых сил (что вовсе не противоречит реальной «путаннице» позиций конкретных людей в революции. И надо понимать при этом, что уровень развития экономических условий жизни людей того времени определяет рамки социальных революций, за пределы которых революции выскочить не могут, хотя и пытаются (иногда только идеологически, иногда только политически, иногда навязывая экономике отношения, к которым она не готова, устраивая заговоры, казня врагов народа и т. д.) Яркий пример перепрыгивания Робеспьер и Бабеф (закон маятника по Марксу).</p><p>Только экономически и классово ни одну революцию не понять и не объяснить, это в дискуссии участники уловили правильно. Только Маркс здесь не причем.</p><h2 id="о-моеи-научнои-судьбе-о-диамате-и-истмате-о-марксизме" tabindex="-1"><a class="header-anchor" href="#о-моеи-научнои-судьбе-о-диамате-и-истмате-о-марксизме"><span>О моей научной судьбе, о диамате и истмате, о марксизме</span></a></h2><p>2010-05-12 в 11:44</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm#form" target="_blank" rel="noopener noreferrer">marianne68</a>. Глубокоуважаемая Вальтраут! (извините, что обращаюсь просто по имени)</strong></p><p><strong>Позвольте Вас поприветствовать, немного помню Ваши работы 80-х, но никогда не думала, что смогу с Вами побеседовать, и прежде всего поблагодарить — за то, что Вы, в отличие от большинства философов и историков, после развала Советского Союза не поторопились откреститься от своих трудов и от своих взглядов.</strong></p><p><strong>И первый вопрос, с этим связанный. Вам приходилось сталкиваться с трудностями на этой почве, например, в издательствах, на конференциях, по административной линии, или просто в частных отношениях с коллегами и студентами?</strong></p><p><strong>В. Шелике</strong>. Трудности, конечно, были, но не только они.</p><p>С одной стороны, в 1975 году мою первую монографию «Социальная революция: общее и особенное» отклонил Политиздат (его отзыв есть у меня на сайте (в «Мысли по поводу»).</p><p>А с другой стороны, именно рукопись этой монографии (вполне безобидной для истмата с моей современной точки зрения,) стала основанием для приглашения меня (беспартийной!) с 1977 по 1989 год постоянным участником ежегодных закрытых симпозиумов АОН при ЦК КПСС по теоретическим проблемам революции, поднимаемым и не решенным в международном коммунистическом движении. Материалы симпозиумов издавались под грифом «Для служебного пользования», т. е. не для всеобщего обозрения. Их «секретность» диктовалась и тем соображением, чтобы ненароком не навредить авторам, найденным по всей стране по принципу наличия у них способности и мужества к самостоятельному размышлению над актуальнейшими теоретическими проблемами современности.</p><p>А в Киргизии на меня, естественно, налетали некоторые местные истматчики, они выкидывали из сборников кафедры философии мои уже набранные статьи, шумели на тему, что «вечно Шелике оригинальничает и т. д.».</p><p>А в 1972 году меня на факультете вообще захотели не выбирать на следующий пятилетний срок доцентом в Кирг. гос. университете. С этой целью целая университетская комиссия разбиралась в «моих научных грехах», ретиво выискивая следы оппортунизма... Спас меня ректор, тоже историк. Два года подряд ректор своим приказом за какие-то нарушения научным советом истфака процедурных правил отменял мои перевыборы, пока страсти на факультете не улеглись.</p><p>На истфаке под моим руководством затем была создана научно-исследовательская группа из студентов и моих неофициальных аспирантов. Мы сами издавали свои сборники трудов, а местный главлит, в лице служивших там милых дам, без задержки их пропускал. Да и многие местные философы нас в это время уже активно поддерживали и давали положительные отзывы на наши статьи.</p><p>Кроме того нашу исследовательскую группу постоянно приглашал на координационные совещания Институт философии АН СССР, и наши выступления печатались в материалах этих совещаний.</p><p>А вот местное киргизское КГБ через моего приятеля юриста однажды передало свою «просьбу», чтобы я сама закрыла свой Методологический семинар, на что я приятелю ответила: «Скажи им, что, если КГБ уже и Маркс не нравится, то пусть они сами себя проверят на идейную чистоту и верность марксизму». Не знаю, передал ли приятель эти слова по назначению, но мой кружок на факультете остался.</p><p>А вот декан каждый год все снова и снова пытался методологический семинар прикрыть, как «не профильный для истфака», как «кружок философский, а не исторический» и т. д. Но кружок, тем не менее, оставался на факультете.</p><p>В 1984 году моя вторая готовая, завершенная в 1983 году, монография, на этот раз по Марксу, была отклонена изд. «Мысль». Следом эта же монография была положена в долгий ящик в АН Кирг. ССР. А в 1991 году издательство «ИЛИМ» АН Кирг. ССР неожиданно издало эту же монографию «Исходные основания материалистического понимания истории» (по работам К. Маркса и Ф. Энгельса 1844–1846 гг.» есть на моем сайте), без каких либо усилий или напоминаний с моей стороны (я сама в 1989 году уже вернулась в Москву, и во Фрунзе (Бишкеке) уже не бывала).</p><p>Такая вот противоречивая научная жизнь получается.</p><p>Вывод: у ученых советского периода кроме тех вариантов выбора, которые на Вашем сайте уже верно перечислены, был еще один выход — уехать из столицы в глубокую периферию. И там, в глубинке продолжать, продолжать и продолжать думать и писать, пусть в начале только в стол.</p><p>Десять лет в Ошком пединституте (на Юге Киргизии) с 1960 по 1969 год меня в местных научных трудах вообще не печатали, за исключением двух страничек тезисов моего выступления о социальной революции. После этой публикации местная ректорша приказала мой спецкурс о социальной революции исключить из программы для студентов истфака. Но наша кафедра этот спецкурс за мной все равно сохранила, только под другим названием.</p><p>В результате, когда в 1976–77 годах по всему Советскому Союзунаучный совет АОН ПРИ ЦК КПСС искали специалистов по теории социальной революции, у меня на руках уже была рукопись монографии, а не только одни распрекрасные идеи в голове.</p><p>Думаю, что в Москве я, вполне возможно, и не выжила бы.</p><p>Дело в том, что в Киргизии у меня все годы были студенты, которым я читала лекционные курсы по Новой истории и спецкурсы по своей научной теме, и таким образом у меня была возможность хоть как-то внедрять свои «оппортунистические взгляды» в юные головы. А вот в Москве, я понимаю, мне такую вольную жизнь никто бы не позволил.</p><p><strong>Marianne. Второй вопрос. Я училась в университете, когда у нас преподавались традиционно диалектический материализм и исторический материализм. Первый — замечательно. Второй — на «тройку с плюсом». Как я понимаю по разговорам с моими сверстниками, не мне одной так повезло. Может быть, с этим и связано отчасти то, что, применяя концепцию Маркса к истории, многие оказываются в тупике, или впадают в упрощение, или отказываются от применения вовсе? А как думаете Вы, разделение на диамат и истмат методологически оправдано?</strong></p><p><strong>В. Шелике</strong>. Разделение диамата и истмата методологически совершенно не оправдано, ибо они едины. Более того, сам Маркс не отделял в отдельную отрасль своей теории также и так называемый научный коммунизм. В материалистической теории истории Маркса диалектика пронизывает теорию истории, так же как и «Капитал». Каждый категориальный ряд у Маркса целостен, диалектичен (таит в себе противоречия и развитие) и каждый категориальный ряд доводится до определения коммунизма в тех понятиях, которые относятся к данному уровню обобщения (т. е. в понятиях именно данного категориального ряда).</p><p><strong>Marianne. Вопрос третий. Собственно говоря, очевидно, что любой «-изм» — результат коллективного сотворчества, часто не одного, а нескольких поколений мыслителей. И все же, что для Вас означает «марксизм»? Является он развитием взглядов самого Маркса или же, наоборот, принципиально противоречит им?</strong></p><p><strong>За ответы буду очень признательна. С уважением, Марианна Петрович.</strong></p><p><strong>В. Шелике</strong>. Марксизм, который проповедовался в учебниках по истмату, и в таком виде засел в головах нашей интеллигенции, писался в основном авторами, которые марксоведами сами не были, они Маркса сами досконально не исследовали. И из учебника в учебник эти авторы просто повторяли некоторые положения из теории Маркса, но так, что из марксовой теории истории «выпадал» живой человек, не было там места действительным индивидам, существовали только общество, классы и классовая борьба и еще партия нового типа. Ведущие положения истмата (о противоречиях между производительными силами о производственными отношениями, о базисе и надстройке, о законе смены общественно-экономических формаций через социальную революцию и т. п.) были взяты у Маркса, но были лишены философской глубины, их несусветно упростили, порой даже исказили. А в результате истмат не смог представить Марксову теорию истории в ее целостности. Но примитивизация теории Маркса сделала зато возможным превращение марксизма в доступную государственную религию (идеологию), опирающуюся всего на несколько незыблемых канонов. Опричники от государственной истматовской идеологии-(религии) действовали по принципу: шаг влево или шаг вправо от истмата и прощай научная головушка. Такой «марксизм» я и называю истматом.</p><p>Всеобщее распространение и торжество истмата в умах граждан было идеалом государства. Но проводившаяся «борьба за верность идее коммунизма и за чистоту марксизма-ленинизма» не была абсолютно победоносной. В то же самое советское время были в стране и многочисленные ученые, которые сами исследовали труды Маркса, издавали статьи и книги о результатах своего прочтения Маркса. Сторонники этого направления советского марксизма углублялись в теорию Маркса, отстаивали гуманизм, присущий теории Маркса, на гуманизм опирались и популяризировали «гуманистический марксизм», как принято сегодня называть такую группу советских философов... Однако, советские марксисты, за редким исключением (а такие тоже были!), Маркса, все-таки, не развивали. А вот тех своих коллег, которые «смели развивать неприкасаемое верное учение» они же нередко вполне искренне подвергали остракизму, хотя в официальных партийных документах демагогически все время и звучал призыв к развитию марксизма-ленинизма и к борьбе против догматизма. Тут, в этой борьбе в среде философов-марксистов было намешано много чистоты и всяческой нечисти действительных помыслов участников и не участников в компаниях травли своих же товарищей по цеху.</p><p>А сегодня, в силу того, что по сравнению с XIX веком кардинально изменился сам мир и развилась наука (наше знание) о мире, существует насущная потребность не только в адекватном понимании теории Маркса, но и необходимость и возможность в ее развитии.</p><p>В нашей стране развитие марксизма сегодня вовсе не самое популярное направление научной мысли. Большинству гуманитариев кажется самым верным просто выкинуть любой марксизм, да и Маркса в придачу, на свалку истории. Снова в головах у современной интеллигенции торжествует не знание, а сплошная идеология, только теперь вроде бы перевернутая шиворот навыворот, но она же, родимая.</p><p>С уважением, В. Шелике. 13 мая 2010 г.</p><hr><p>2010-05-18 в 19:54</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">L del Kiante</a>. Оксана, передайте синьоре Вальтраут мою благодарность за ответ и наилучшие пожелания. Я бы лишь продолжил вопрос marianne68: а сегодня Вы не испытываете дискомфорта в научном сообществе, оставаясь приверженцем теории Маркса?</strong></p><p><strong>В. Шелике.</strong> Нет, не испытываю, поскольку мои «мыслишки о Марксе» востребованы. Более 50000 кликов (на сентябрь 2010 года) за два с половиной года на мой сайт свидетельствуют об интересе к Марксу, о нужности и моих размышлений о теории Маркса. Потихонечку печатаются и мои статьи на русском и на немецком, я выступаю на конференциях и меня на них снова приглашают. Какой тут может быть дискомфорт в научном сообществе? Не все относятся положительно? Так это же нормально, люди имеют право думать иначе, чем я, воспринимать мир совсем иначе, чем Маркс, тем более что век сегодня ХХI, а не XIX. Да и разочарований в мире у людей накопилось сегодня выше крыши, и первое, что издревле приходит в голову разочарованному человеку, это найти «виноватого», и закидать его камнями. Подобная ругань-преследование в адрес Маркса меня эмоционально не трогает и не удивляет, я знаю ее социальные истоки и сверху и снизу. Кроме того ни одно новое прочтение Маркса (о необходимости которого писал Гефтер еще в 60-ые годы) не может быть единственно верным и с ходу быть принято даже сторонниками Маркса, а о его противниках и говорить нечего.</p><h2 id="о-марксизме-и-позитивизме" tabindex="-1"><a class="header-anchor" href="#о-марксизме-и-позитивизме"><span>О марксизме и позитивизме</span></a></h2><p>2010-05-12 в 22:18</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm?from=last" target="_blank" rel="noopener noreferrer">L del Kiante</a>. Уважаемая синьора Шелике! Благодаря нашему сообществу, и я наконец познакомился с Вашими работами, хотя пока еще поверхностно. Вопрос же у меня общего характера: как считаете Вы, взгляды Маркса можно отнести к позитивистским? И отсюда следует другой вопрос: то часто отрицательное, вплоть до полного отрицания, отношение к взглядам Маркса в «постиндустриальную эпоху», связано ли оно с пошатнувшимися позициями позитивизма в целом? Это помимо политических и идеологических причин. С почтением.</strong></p><p><strong>В. Шелике.</strong> Я не специалист по позитивизму и не занималась соотношением взглядов Маркса к современным общественным теориям. Могу только сказать, что сами понятия постиндустриальное общество или современное понятие общество знаний, по-моему, выведены из ограниченного понимания производительных сил то как индустриальных (техника), то как интеллектуальных (знания, наука), что, имеет право на существование, ибо улавливает определенные изменения, происходящие с человечеством в нашем веке. Но эти понятия охватывают вовсе не все факторы и тенденции развития человечества, а перспективу все-таки искажают (и в этом, скорее всего источник падения популярности теории постиндустриального общества, оказавшегося неспособным снять существующие противоречия мира).</p><p>Мне лично более по душе Марксово понятие Человеческое (человечное) общество (Menschliche Gesellschaft), как исходное определение того общества, к которому сегодня (осознано или неосознанно, адекватно или перевернуто) начиная с XIX века движется человечество, чтобы не самоликвидироваться. Это движение вбирает сегодня и развитие техники, и развитие науки, но не только. Этому альтернативному движению многое способствует, но и многое противостоит в современном мире, но оно продолжается, перестав восприниматься как коммунистическое (тоже крах). Мы на переломе.</p><h2 id="о-вульгаризации-взглядов-маркса" tabindex="-1"><a class="header-anchor" href="#о-вульгаризации-взглядов-маркса"><span>О вульгаризации взглядов Маркса</span></a></h2><p>2010-05-12 в 22:27</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm?from=last" target="_blank" rel="noopener noreferrer">Marty Larny</a>. Глубокоуважаемая Вальтраут, разрешите задать еще один «общий» вопрос. Безусловно, взгляды Маркса, им самим изложенные, подверглись и осмыслению, и вульгаризации, оказавшейся очень живучей. Более живучей, чем прототип. Как Вы считаете, какие именно вульгаризации нанесли самый серьезный урон Марксу как социальному мыслителю — скажем, в глазах наших современников? Очень рад, что узнал о Ваших работах — это то, что хочется читать. Эмиль Пашковский.</strong></p><p><strong>В. Шелике</strong>. Урон Марксу нанесен через:</p><ol><li><p>Обыденное толкование бытия (Sein) как чего-то, что сродни быту, и представление о том, что Маркс, якобы, считал, что быт определяет сознание (Bewusstsein).</p></li><li><p>Подозрение, что Маркс отрицал роль идей в истории, и все истоки действий людей сводил к каким-то материальным (бытовым?) мотивам.</p></li><li><p>Трактовка производительных сил как технических факторов производства, и представление о том, что развитие техники само по себе уже обеспечивает человечеству прогресс в его развитии.</p></li><li><p>Трактовка производства как хозяйствования (промышленность, сельское хозяйство, торговля) и отнесение семьи, школы, ВУЗА, медицины к непроизводственной сфере (которую и финансировать можно по остаточному принципу).</p></li><li><p>Трактовка производственных отношений только как отношений людей к людям вне наличия в производственных отношениях и отношений людей к природе. Отсюда некая готовность совершенствовать производственные отношениям людей к людям и очень долгое пренебрежение в СССР к экологическим проблемам.</p></li><li><p>Потеря роли и места общения-коммуникации (Verkehr) в практическом процессе развития человечества. Трактовка общения как раннего понятия, якобы, позже замененного Марксом на понятие производственные отношения. В результате готовность с энтузиазмом совершенствовать производство (как хозяйствование), а что в результате модернизации будет с человеческим общением-коммуникацией между людьми просто наплевать. Да и дороги тоже (средство общения-коммуникации) можно надолго оставлять в жутком состоянии, главное, увеличивать производство и тогда общественный прогресс будет обеспечен. А получается «как всегда».</p></li><li><p>Убежденность в том, что отчужденный характер труда, от которого по Марксу люди бегут как от чумы, обусловлен наличием частной собственности (а у Маркса наоборот, отчужденный характер труда обуславливает частную собственность). Отсюда иллюзия, будто ликвидация частной собственности и превращение ее в государственную ликвидирует отчужденный характер труда, и любой труд отныне становится сплошным наслаждением. Ан, нет, и в СССР к труду пришлось принуждать разными драконовскими законами, в том числе эффективно используя и рабский труд заключенных, как в свое время это делал какой-нибудь Фридрих Второй в средневековой Германии.</p></li><li><p>Иллюзия о том, что рост производительности труда является единственным, самым главным критерием и условием прогрессивного развития человечества. И абсолютное непонимание положение Маркса о том, что труд постепенно убывает, а в будущем исчезнет из жизни людей, которые заменят его на СамоДеятельность и вплотную займутся своим общением. (Такую тенденцию развития человечества Маркс увидел уже в далеком XIX веке, ибо уже там были ростки).</p></li><li><p>Иллюзия о том, что коммунизм неизбежен, что «Все дороги ведут к коммунизму», тогда как у Маркса коммунизм вовсе не цель человечества, не состояние, которое можно навязать обществу, а долгосрочное действительное движение, которое, как мы видим сегодня, может и прерваться через самоуничтожение человечества или через природный катаклизм.</p></li><li><p>Иллюзия о том, что для перехода к социализму, достаточно изменить материальные условия жизни людей, оставив нетронутым отчужденный характер труда.</p></li><li><p>Разделение Маркса на раннего, незрелого, и позднего, зрелого. Это сделало возможным пренебречь первым великим открытием Маркса — открытием им законов развития истории человечества в 1844–46 годах. А материалистическую теорию истории «зрелого Маркса» выводили из популяризаторской работы «Манифест коммунистической партии» и свели целостную теорию материалистического понимания истории к паре страниц из Предисловия к «Критике политической экономии» 1857 года».</p></li></ol><p>Достаточно?</p><hr><p>2010-05-16 в 22:05</p><blockquote><p><strong>В. Шелике.</strong> А материалистическую теорию истории «зрелого Маркса» выводили из популяризаторской работы «Манифест коммунистической партии» и свели целостную теорию материалистического понимания истории к паре страниц из Предисловия к «Критике политической экономии» 1857 года.</p></blockquote><p><strong>Marty Larny. Дело даже не в том, что это «популяризаторская работа» — это политическая программа, а программа не может и не должна отразить всю философскую концепцию, или она уже не программа.</strong></p><p><strong>В. Шелике.</strong> Абсолютно согласна с таким уточнением.</p><p><strong>Marty Larny: Не соглашусь с пп. 5:</strong></p><blockquote><ol start="5"><li>Потеря роли и места общения-коммуникации (Verkehr) в практическом процессе развития человечества.</li></ol></blockquote><p><strong>Допускаю, что специально над этой проблемой мало кто задумывался, но стихийно, или, вернее, в силу концентрации производства и т. наз. «территориально-производственного принципа», несмотря на отсутствие сегодняшних средств связи, коммуникация было гораздо интенсивнее и содержательнее. Это просто мой личный опыт, в том числе репортерский.</strong></p><p><strong>В. Шелике.</strong> Я допустила неверную оговорку. Надо было написать 5) Потеря понятия общение-коммуникация (Verkehr) в теории исторического материализма.</p><p>В действительности общение, конечно, потеряно быть не может, без общения и дети на свет не рождаются. Спасибо Вам за то, что отреагировали на получившуюся несуразицу.</p><p>В материалистическом понимании истории Маркса Verkehr является парной категорией с производством (Produktion) и трудно переводимо на русский язык одним словом. Через Verkehr люди не только детей рожают, и не только общаются между собой. Люди в своем Verkehre сами же еще и искажают (феркерят) мир и сами же создают искаженный мир (verkehrte Welt), бесчеловечность которого вызывает их гнев или отчаяние и протест в революциях.</p><p>Загляните в мой сайт, там много о Verkehr e.</p><p><strong>Marty Larny: не соглашусь с пунктом</strong></p><blockquote><ol start="7"><li>Иллюзия о том, что рост производительности труда является единственным, самым главным критерием и условием прогрессивного развития человечества.</li></ol></blockquote><p><strong>Насколько я помню советские времена, все же рост производительности труда рассматривался как обязательный фактор развития в конкретном обществе.</strong></p><p><strong>В. Шелике.</strong> Вот тут Вы зря не согласились, ибо проблема гораздо сложней, и господство этого критерия прогресса в СССР вовсе не доказательство его всеобщности, а значит необходимости и в будущем.</p><p>Думаю, что рост производительности труда является критерием прогресса только в период предистории человечества, т. е. в период варварстве и в период цивилизации. Но для коммунизма он не годится.</p><p>Дело в том, что живой человеческий труд на всем протяжении периода цивилизации постепенно вытесняется из экономической жизни людей, что обеспечивает капиталисту дополнительную прибыль, уменьшая долю переменного капитала, идущего на зарплату (прогресс с точки зрения капиталиста), а рабочего выкидывает в отряд безработных (регресс в жизни рабочего). Рабочий в результате, конечно, чувствует на собственной шкуре насколько капитализм бесчеловечен, и это стимулирует его на борьбу (прогресс). Но борьбу рабочий ведет не только под знаменем действительного освобождения всего человечества от капитализма (прогрессивно), но и разрушает машины, дает втянуть себя в войну с рабочими других стран ради интересов своей буржуазии, поддерживает фашистов, раздражается на иногородних и инородцев, сжигает автомобили невинных сограждан и т. д. (регресс).</p><p>Вместе с тем рост производительности труда высвобождает в обществе кучу свободного времени (прогресс). Но безработный, да и рабочий, как правило, не знают куда толком девать свободное время при ухудшении уровня своей жизни, которое он до селе тратил на развлечения и потребление вещей... Отсюда пьянство, наркомания, рост насилия и т. д. в рабочей (безработной) среде (регресс), а также выступления против снижения уровня социальной защиты (посмотрите на Грецию сегодня), которое воспринимается как катастрофа.</p><p>Рост производительности труда, умножает общественное богатство, что позволяет обществу содержать безработного на социальном пособии (прогресс). Но при общественной ориентации на престижность для каждого иметь рабочее место, и унизительность оказаться на социальном пособии (не у всех так, но у многих именно так), свободное время воспринимается не как «нечаянный» подарок со стороны общества для осуществления в свободное время саморазвития себя как человека (прогресс). Свободное время зачастую воспринимается как ящик Пандоры, из которого выползает целый клубок скуки, унижений и ощущений своей не востребованности (регресс для саморазвития личности, источник алкоголизма. наркомании и т. д.). Да и в СССР рабочие не очень жаловали в своем трудовом коллективе тех, кто перевыполнял план (прогресс), ибо это вело к увеличению нормы для всех, что требовало от менее проворного рабочего навязанной ему своим же товарищем интенсификации труда (прогресс), но одновременно влекло за собой рост уровня усталости, раздражительности, недовольства собой и работой у рабочего. А на усталую голову в свободное время и выпить не грех, и т. д. (регресс).</p><p>Так что рост производительности труда в период цивилизации (куда относится и СССР) таит в себе массу проблем в плане условий для прогрессивного, всестороннего развития трудящегося.</p><p>Вряд ли, на этом клубке противоречий можно строить человечное общество, не наступая все вновь и вновь на одни и те же грабли.</p><p>Какой выход видел из этого заколдованного круга Маркс? Возможно вы удивитесь, но наблюдая тенденцию вытеснения живого человеческого труда из производства и видя, что труд не доставляет рабочему наслаждение, Маркс сделал вывод об исчезновении труда при коммунизме. Переход человечества к коммунизму по Марксу осуществляется кроме всего прочего и через переход людей к СамоДеятельности, к наделению себя самих деятельностью, которая по душе человеку и доставляет ему наслаждение. И некоторым людям даже во времена Гете (который уже размышлял о замене труда творчеством), а также сегодня, уже «везет» в их жизни. Некоторые (а скорее сего даже многие) люди заняты не тем (или не только тем), что навязано им обществом для зарабатывания зарплаты, а тем делом, которое доставляет этим людям радость в самом процессе деятельности, и результаты которой нужны и другим людям. Некоторые люди занимаются такого рода разными делами даже бесплатно, (если есть у них какой-то иной, кроме найма на нелюбимую работу, источник существования).</p><p><strong>Marty Larny. Тогда следующий вопрос: это все на «совести» исключительно советских идеологов? Можно ли сказать, что на Западе Маркс был прочитан и понят глубже, и какие это прочтение имело следствия на практике?</strong></p><p><strong>В. Шелике.</strong> Нет, не думаю, что можно говорить об исключительной «вине советских идеологов» и «совесть» тут мало что объяснят в причинах возникновения истмата. И на Западе материалистическая теория истории Маркса тоже еще не понята во всей ее целостности. И тому существует множество причин, и общественных, и личностных. И одна из них в том, что мыслить так диалектически, как умел это Маркс, никому из его последователей пока не удалось. Адекватно понять теорию истории Маркса под силу только коллективному творчеству многочисленных исследователей Маркса, которым и предстоит решить задачу по воссозданию материалистического понимания истории Маркса как целостной теории и написать доступный для массового читателя соответствующий учебник. Маркс учебник по материалистической теории истории не написал и нам не оставил.</p><h2 id="о-типологии-революции" tabindex="-1"><a class="header-anchor" href="#о-типологии-революции"><span>О типологии революций</span></a></h2><p>2010-05-16 в 10:55</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Nataly Red Rose</a>. По-Вашему, есть ли смысл и реальное наполнение у термина «буржуазная революция»? Если да, то в чем Вы видите это наполнение?</strong></p><p><strong>В. Шелике.</strong> Революции отличаются по типу (каково формационное содержание революции, например капиталистическая революция, коммунистическая революция), по характеру (по тому классу, в интересах которого осуществляется революция, например, буржуазная революция, пролетарская революция), по форме (по форме классовой борьбы, например, мирная революция и немирная революция, революция снизу и революция сверху), по той сфере жизни людей, в которой происходит революция (экономическая революция, политическая революция и т. д.), по той отрасли производства, в которой происходит революция (аграрная революция, промышленная революция), по результатам (завершенная и незавершенная), по продолжительности во времени всех или отдельных циклов обострения и затухания остроты классовой борьбы (революция в широком смысле или революция в узком смысле), по целостности всего процесс смены формаций (эпоха социальной революции) и др. На моем сайте в разделе «О революциях» есть об этом статьи.</p><p><strong>Nataly Red Rose. Всегда ли буржаузная революция является межформационной, или может быть и внутриформационной?</strong></p><p><strong>В. Шелике.</strong> Буржуазия сама по себе неоднородна, и представлена в истории крупной и мелкой финансовой, торговой, промышленной, а сегодня бурным расцветом целого букета крупной и мелкой спекулятивной, мафиозной, рэкетирской, мошеннической буржуазии. У каждой из этих групп буржуазии свои интересы порой прямо противоположные. Поэтому происходят и внутриформационные буржуазные революции, когда, например, на смену политическому господству финансовой буржуазии, у которой свои интересы по формуле <code>Д — Т — Д</code> или даже <code>Д — Д</code>, приходит торговая буржуазия в союзе с промышленной буржуазией, да еще и когда к власти и рвется мелкая буржуазия, у которых тоже свои интересы по формуле <code>Т — Д — Т</code>. Весь XIX век во Франции наполнен этой политической борьбой за власть внутри класса буржуазии. Так что внутриформационные революции не только возможны, но и действительно происходят (добавьте к этому промышленную революцию, кибернетическую революцию, которые тоже внутриформационные и т. д.).</p><hr><p>2010-05-20 в 13:49</p><p><strong>Nataly Red Rosa. Большое спасибо Вальтраут Шелике за ответ! А я продолжу ту же тему, о буржуазной революции. Конкретно о нашей Великой французской. Вот 3 признака, вокруг которых в историографии идет спор, и у нас тоже: по целостности всего процесс смены формаций (эпоха социальной революции), по типу (формационное содержание революции, например капиталистическая революция...), по характеру (по тому классу, в интересах которого осуществляется революция, например, буржуазная революция...).</strong></p><p><strong>Против: ВФР не была целостным процессом, т. к. смены экономической формации не произошло, и уж во всяком случае развитию капитализма дорогу не открыло, а осуществляли ВФР разные группы, буржуазия в ней не выступала как единый класс.</strong></p><p><strong>За (это моя точка зрения): а нельзя искать смену формации в одной точке времени и пространства! С одной стороны, ВФР продолжает цепную реакцию межформационных революций 16-17 вв. в Европе, с другой — иницирует буржуазные революции следующего века. Завершились они или не завершились, как, например, испанская или в немецких княжествах, но попытки были. И наступления капитализма в одночасье ожидать нельзя. Социальные и политические предпосылки для него — да, появились в ходе и в результате ВФР, тут я солидарна с Е. М. Кожокиным. Так это и главное. Буржуазия... Если понимать под ней именно класс по Марксу (синоним «капиталистов», класс, противоположный классу наемных рабочих), то можно выделить и общий интерес, и общие достижения. Если оперировать термином «буржуазия» в контексте 18 века (идентификация, самоидентификация), тогда, конечно, столь общей картины не будет. Хотя...</strong></p><p><strong>А как думаете Вы — буржуазная ВФР или нет? И если да/нет, то как бы Вы определили соответствие этим критериям нашего исторического события?</strong></p><p><strong>В. Шелике.</strong> Полностью согласна с Вашей точкой зрения и Вашей аргументацией, и выводом о том, что «нельзя искать смену формаций в одной точке времени и пространства» (как, впрочем, и наступления в одночасье социализма, или коммунизма как человечного общества).</p><p>В поддержку Вашей позиции могу только добавить:</p><p>1) Не верно ожидать от революции в узком смысле (1789-94 (99)) тех же результатов, которые выполняет революция в широком смысле (1789-1870). Это на примере Франции.</p><p>2) Для понимания всей целостности исторического процесса смены общественных формаций в эпоху социальной революции в период цивилизации необходимо использовать группу понятий экономическая революции, политическая революция и общественная революция. Надо исследовать совпадения и различия каждой из них а) по времени их начала и ступеням их развития, б) по методом их осуществления в разное историческое время, б)по результатам их завершенности или незавершенности относительно начала эпохи уже другой по типу социальной революции.</p><p>3) Для понимания конкретно-исторической сложности революционных процессов смены формаций необходимо учитывать неоднородность класса, в интересах которого на разных этапах осуществляются экономическая, политическая и общественная революции, ибо эти экономические, политические и общественные интересы разных групп буржуазии не только сходны, но и различны.</p><p>Но! В процессе революции каждая из групп буржуазии ради своей победы выдает именно свой интерес за всеобщий интерес всего класса или даже всего человечества, иначе ей трудно найти союзников и одержать победу. Но именно поэтому революции полны мифов и иллюзий, куда надо добавить и исходную иллюзорность самоопределения индивидами себя самих и своих классовых интересов.</p><p>Но вместе с тем революции в узком смысле, при всех сплетениях в них человечного и обесчеловеченного, истинного и ложного, мифов и реальности в одном флаконе, не случайно названы праздником угнетенных, поскольку манипуляция и обман, а также собственные иллюзии остро осознаются народными массами (тоже неоднородными) именно в такое бурное время революций в узком смысле и не только это.</p><p>Для меня ФБР, конечно, буржуазная революция, поскольку именно ее интересы (разные) поэтапно и осуществлялись в конечном счете во ФБР и дальше во Франции в течение XIX века (и не только во Франции).</p><p>4) Для понимания революции в широком смысле в эпоху цивилизации, недостаточно исследовать только состояние и развитие внутреннего общения-коммуникации до и в ходе революции (и в узком и в широком смысле). Необходимо исследовать (учитывать) и внешнее общение-коммуникацию (Verkehr) на протяжении революции (интервенция, революционные войны, континентальная блокада и т. д.). По Марксу состояние каждой нации в истории зависит не только от ее внутреннего производства, но также от ее внутреннего и внешнего общения. И это относится и к революционным периодам истории... Истматовское положение о невозможности, якобы, экспортировать революции этому пониманию роли внешнего общения очень мешает и противоречит.</p><p>И поэтому Вы правы, когда ставите ФБР в контекст общеевропейской истории и общеевропейского процесса смены формации (в которой участвуют не только Робеспьеры и Гарибальди, но и Наполеоны и Бисмарки) и ставите вопрос о пространстве революции.</p><h2 id="о-критериях-прогресса" tabindex="-1"><a class="header-anchor" href="#о-критериях-прогресса"><span>О критериях прогресса</span></a></h2><p>2010-05-23 в 12:25</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Синяя блуза</a>. Уважаемая Вальтраут! I) Как Вы рассматриваете критерии экономического, социального и духовного прогресса? Вообще, есть ли они? (Некоторые сомневаются, говоря, что любые критерии всегда только субъективны).</strong></p><p><strong>В. Шелике.</strong> Предлагаю мой развернутый ответ на вопрос о критериях прогресса пока отложить. Дело в том, что 4 июня 2010 г. в ИНИОНе состоится конференция, на которой я собираюсь выступить как раз по вопросам о всеобщих критериях прогресса. Во всяком случае тезисы выступления я туда уже выслала. После конференции мне, возможно, придется написать текст своего выступления, если его станут публиковать, а по развернутому тексту ответить затем сжато на Ваш вопрос мне будет проще.</p><p><strong>Синяя блуза. А пока вот что о прогрессе для дальнейшего размышления:</strong></p><p><strong>А) «Все развитие человеческого общества после стадии животной дикости начинается с того дня, как труд семьи стал создавать больше продуктов, чем необходимо было для ее поддержания, с того дня, как часть труда могла уже затрачиваться на производство не одних только жизненных средств, но и средств производства. Избыток продукта труда над издержками поддержания труда и образование и накопление из этого избытка общественного производственного и резервного фонда — все это было и остается основой всякого общественного, политического и умственного прогресса.» (Ф. Энгельс, «Анти-Дюринг»)</strong></p><p><strong>В. Шелике.</strong> Приведенные Вами слова Энгельса о значении роста производительности труда выявляют а) истоки, начало прогресса в период варварства и б) условия, а также сферы прогресса только в период цивилизации, когда еще существует экономика, а коммунизм не экономическая, а постэкономическая формация(!), и когда еще существует политика, т. е. когда существует государство, которого при коммунизме не будет(!).</p><p>По существу варварство и цивилизация охватывают весь процесс возникновения, развития (через рост разделения) и начала исчезновения труда. А по сему рост производительности труда не всеобщий критерий, если согласиться с Марксом в том, что при коммунизме (в человечном обществе) труд из жизни людей исчезает и заменяется СамоДеятельностью.</p><p>Возникает, конечно, проблема существует ли всеобщий критерий прогресса для всей истории человечества, (прошлой, настоящей и будущей), если даже рост производительности труда такую функцию не выполняет.</p><p><strong>Синяя блуза: Б) Второй критерий прогресса — КАК этот избыток распределен между членами общества. Если по принципу 20:80 — 80:20, а тем более 1:90, то в прогрессе позволительно усомниться.</strong></p><p><strong>В. Шелике.</strong> Добавленный Вами критерий прогресса (20:80, 1:90) по распределению «излишков», требует еще и определения между кем и кем, с вашей точки зрения, осуществляется распределение. Между богатыми и бедными? Капиталистами и рабочими? Западом и Востоком? Севером и Югом? Мужчинами и женщинами?</p><p>А к человечному обществу какой критерий распределения применим?</p><p>Критерий прогресса по способам распределения общественного богатства необходим, но он требует разработки. И он, конечно, не единственный критерий прогресса.</p><p><strong>Синяя Блуза: В) А вот что <a href="http://www.diary.ru/~vive-liberta/p94081604.htm" target="_blank" rel="noopener noreferrer">добавила Marianna-S**</a>: а третий критерий — на производство ЧЕГО ИМЕННО расходуется этот избыток продукта труда, и обществом в целом, и отдельными его индивидами.</strong></p><p><strong>В. Шелике.</strong> А вот третий критерий прогресса по тому, что именно производится в обществе в качестве излишка общественного богатства и на что оно расходуется, в самую точку. Хотя сразу оговорюсь, что это, конечно, тоже не единственный критерий прогресса.</p><p>Чтобы ответить на вопрос каковы критерии прогресса и существу(ю)ет ли вообще всеобщи(и)й критери(и)й прогресса, надо помнить, что в период варварства и в период цивилизации прогресс и регресс шагают в обнимку друг с другом, и понять один без другого просто невозможно.</p><p>Люди исходно (уже и в период варварства) не только трудились и создавали средства жизни (прогресс), но они еще и воевали, убивали (порой поедали) друг друга, и соответственно трудились также и по созданию средств смерти (регресс).</p><p>И сегодня, на современном этапе цивилизации, это не изменилось, с той, однако, разницей, что современные средства смерти способны уничтожить все человечество, чего они в прошлом не могли.</p><p>А отсюда и возникает актуальный вопрос о будущем человечества, в том числе и вопрос о всеобщих критериях прогресса человечества (есть они или нет их?). И еще: в человечном обществе (коммунизме) единство прогресса и регресса сохраняется? Да или нет?</p><h2 id="о-классах-о-социальных-и-общественных-отношениях" tabindex="-1"><a class="header-anchor" href="#о-классах-о-социальных-и-общественных-отношениях"><span>О классах, о социальных и общественных отношениях</span></a></h2><p>2010-05-23 в 12:25</p><p><strong>Синяя Блуза. II) А как Вы отвечаете на вопрос, где они «начинаются и заканчиваются», общественные классы, ЧТО ИХ ДЕЛАЕТ КЛАССАМИ?</strong></p><p><strong>В. Шелике.</strong> Ответ на данный вопрос требует четко разграничивать общественные отношения (общество) и социальные отношения (социум, социальный организм) как понятия разных уровней обобщения. (Об этом подробно есть у меня на сайте «Мой Маркс»). Без такого разграничения не понять что такое классы и существуют ли они на самом деле в истории человечества.</p><p>Коротко. Осуществляя социальную деятельность, создавая социальные отношения (см. три всеобщие стороны социальной деятельности по Марксу на сайте «Мой Маркс») действительные индивиды создают также и социальные сообщества людей, которые существуют в исторической действительности (завод, семья, армия, село, школа, страна и т. д.) В этих сообществах люди что-то созидают или что-то разрушают, они общаются друг с другом, сотрудничают или конкурируют, рожают или убивают и т. д. Каждое из таких сообществ формирует какие-то потребности действительных индивидов (материальные и духовные, истинные и ложные, человечные и обесчеловеченные и т. д.). В процессе своей совокупной социальной деятельности действительные индивиды удовлетворяют или не удовлетворяют потребности своей жизни (действительные или кажущиеся, физические или духовные и т. д.).</p><p>Существенно то, что свою принадлежность к таким разным социальным сообществам действительные индивиды осознают: каждый знает когда он сын, солдат армии, покупатель в магазине, житель страны и т. д. Социальная структура любого социального организма лежит на исторической поверхности, и каждый действительный индивид может сделать и делает вывод о своем социальном положении (о социальном статусе каждого) среди других людей (среди всех).</p><p>Каждое из социальных сообществ вносит свой вклад в общую картину мира каждого действительного индивида (через индивидуальный опыт его жизни в том или ином сообществе). Картина мира у индивидов зачастую весьма противоречива, поскольку зачастую противоречивы установки, интересы и т. д. каждой из тех социальных общностей, в которые входит тот или иной действительный индивид в процессе своей жизни. Отсюда в головах людей зачастую существует несусветный хаос представлений об их потребностях, об их целях жизни и т. п. И с такой мешаниной в головах действительные индивиды и осуществляют свои исторические деяния, в том числе и во время революций в узком смысле, при том уверенные, что их собственные идеи (теории, модели мира и прочая), конечно, должны определить и результат их действия. Но на самом деле все время получается по Черномырдину «Хотели как лучше, а получилось как всегда». (Хотели Свободу, Равенство и Братство, а получили гильотину и наполеоновские войны, а вдобавок еще и новые возможности для роста эксплуатации, не ограниченной теперь только емкостью желудка феодала и т. д.)</p><p>Решения этой загадки истории о противоречиях между индивидуальными, групповыми, социальными целями (идеалами) действительных участников социальных движений и действительными результатами их действий лежит в необходимости перехода от рассмотрения трех всеобщих сторон социальной деятельности к четвертой стороне — к обществу (как у Маркса). (Подробно см. сайт «Мой Маркс»)</p><p>Общество по Марксу есть ВместеДействие (Zusammenwirken) всех действительных индивидов вместе, как некого целого. ВместеДействие людей существует в истории независимо от того, осознают его люди или не осознают, оно придает историческому процессу, в том числе и социальным движениям, общественный характер.</p><p>Сегодня, используя понятия системного метода, можно сказать, что Маркс открыл общество как системное качество, которым каждый отдельный элемент (действительные индивиды, их групп и т. п.) отдельно не обладает, но которое присуще ему как составной части системы, (по Марксу общественной формации).</p><p>Структура общества (в отличие от многочисленности социальных сообществ) в период цивилизации строится на ВместеДействии (Zusammenwirken) людей друг с другом и на противодействии (Gegeneinanderwirken) людей друг другу, что обусловлено единством и противоположностью составляющих общество классов.</p><p>Классы различаются различными отношениями разных людей к средствам производства, (надо бы добавить и к средствам общения (Vehrkehr): люди владеют или не владеют средствами производства, владеют всеми или частичными и т. д. Эти отношений собственности на средства производства (и средства общения) существуют в обществе независимо от того, осознаны они действительными индивидами или не осознано ими. Отношения людей к средствам производства и к средствам общения, т. е. отношения собственности, разделяют и связывают людей в процессе производства в определенные классы, где один не может существовать (жить) в обществе без другого, тоже независимо от того, осознано это людьми или не осознано.</p><p>Классовые отношения это, если хотите, некая сеть, попав в которую действительные индивиды оказываются разбросанными по разным сторонам общества, на владеющих условиями труда полностью, частично и не владеющими ими вовсе.</p><p>Свое классовое место в обществе индивид может и не осознавать, он даже может отрицать наличие каких-то там «выдуманных», (кстати, вовсе не Марксом(!)), классов. Индивиду видно, к какому сословию он принадлежит, из какого села происходит, а про классы он, возможно, никогда и не слыхал. Но в конечном счете именно классовая структура общества, по Марксу, «виновата» в действительном (неожиданном) результате исторических действий действительных индивидов, (на самом деле, сами того не зная, действующих в интересах того или иного класса).</p><p>Именно классовую структуру общества действительные индивиды и изменяют через социальную революцию, хотя в их головах и душах такое намерение в таких выражениях, как правило, и не существует. Но не идеи правят миром!</p><p>Результат революции беспощадно выявляет в интересах какого класса оказалось «претворение» в действительность распрекрасных идей и благородных намерений каждого действительного индивида, каждой социальной группы людей, каждого известного участника революции .</p><p>Так что не ругайте себя или деятелей ФБР за то, что в их речах и действиях во время революции невозможно увидеть четкое выражение их классовых позиций. Нельзя от французов XVIII века требовать того, что люди и сегодня еще не умеют.</p><p>А вот истмат требовал от ученых-историков выводить действия людей напрямую из их классового происхождения или из их классовой принадлежности, что заставляло, например, Адо писать о революционном крестьянстве и молчать о крестьянстве контрреволюционном, как прозвучало в Вашей дискуссии.</p><p>Разделения социальной деятельности и общественной деятельности в истмате тоже не существовало. Более того, социология, коей активно занимались на Западе, в СССР была объявлена лженаукой, и в СССР право на существование имело только обществоведение. И если истмат все и вся сводил к классам, упрощая многогранность действительной истории, то с другой стороны немало современных социологов отрицают сегодня наличие в истории классов. Последнее тоже шаг назад для научного исследования практического процесса развития человечества.</p><p>И важное. Когда речь идет об уничтожении классов при коммунизме (в человечном обществе), то Маркс имеет в виду не физическое истребление богатых бедными, буржуа пролетарием (как это зачастую понималось, и не только понималось, но и осуществлялось в действительности). Речь идет об уничтожении именно классовой структуры общества, той конкретно-исторической системы отношений, которые связывает действительных индивидов в определенное (капиталистическое) общество.</p><p>Согласно Марксу структура общества в истории человечества меняется в соответствии с изменениями способа производства и изменения форм общения. И этот длительный процесс системной трансформации (как любят сегодня выражаться) Маркс называл эпохой социальной революции, в ходе которой одна общественная формация (система) заменяется другой. Естественно, что такая историческая эпоха не может не вбирать в себя различные, противоположные социальные движения, и самые разные виды классовой (по существу) борьбы.</p><h2 id="о-научности-истории" tabindex="-1"><a class="header-anchor" href="#о-научности-истории"><span>О научности истории</span></a></h2><p>2010-05-27 в 00:01</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Forster2005</a>. Мы часто возвращаемся к проблеме научности истории, к критериям научности гуманитарного знания. И, так или иначе, констатируем, что в истории ВСЕГДА действуют два очень сильных фактора ненаучного характера: субъективная оценка автора (исследователя), складывающаяся у него еще до проведения исследования, и влияние современной ему политической ситуации. Согласны ли Вы с этим? И — нужно ли стремиться нейтрализовать эти факторы или с этим, что называется, ничего поделать нельзя?</strong></p><p><strong>В. Шелике.</strong> Научность истории, каковы критерии? В этой проблеме, по крайней мере, несколько моментов.</p><p>1) Во-первых, если теория не строится на открытых учеными законах функционирования предмета исследования, то такую теории научной назвать нельзя. Научность истории определяется наличием в самой истории законов существования, развития и исчезновения человечества (и его отношений с миром). Эти законы существуют и функционируют в истории независимо от того, открыты они учеными или не открыты, и в этом смысле они материальны. Открытие законов истории и является задачей истории как науки.</p><p>По словам Энгельса именно законы истории Маркс и открыл в материалистической теории истории. И лично я с этим утверждением Энгельса совершенно согласна.</p><p>Материалистическая теория истории Маркса это наука. И историк, владеющий таким научным инструментарием исследования, при наличии источников и т. п. занят именно наукой, а не просто фантазиями на вольную тему.</p><p>2) Каждая теория, претендующая на научность, располагает определенным понятийным аппаратом, которым и пользуются сторонники данной теории. В каждое понятие сторонники одной и той же теории вкладывают одно и то же содержание, хотя бы для того, чтобы понимать друг друга, ибо иначе получится не научная теория, а полнейший кавардак. Зарождающаяся теория всегда полна терминологического кавардака, зрелая теория терминологически упорядочена.</p><p>Современные теории истории, в том числе и материалистическая теории истории Маркса в современных интерпретациях характеризуются полнейшим кавардаком понятийного аппарата. В этом смысле говорить об истории как зрелой науки не приходится.</p><p>3) К тому же, сам предмет исследования — история человечества (и его отношений с миром) существенно отличается от предметов исследования в естественных науках. Дело в том, что сам исследователь-историк все время находится «внутри предмета». (Физик не находится внутри атомного реактора; химик не сидит в колбе, в которой происходит химическая реакция). А вот историк сам, осознанно или неосознанно, является участником исторического процесса своего времени, пытается понять прошлое и настоящее в понятиях своего времени, своего социального окружения и «выйти из истории» не может. Как любой ученый (хотя физики, изобретая атомную бомбу, химики изобретая отравляющие вещества, и т. д. реже это осознают или стараются это не осознавать) историк непосредственно вписан в идеологическую, политическую и прочая духовную жизнь современного ему общества, и подвержен, как Вы верно заметили, «политическому влиянию». И некуда ему от этого деваться.</p><p>Но это тоже закон истории как науки, который, вряд ли, удается «нейтрализовать». Да и стыдиться этого закона историку тоже не стоит. Он же не виноват, что взялся исследовать самый сложный предмет какой только есть в истории человечества — саму эту человеческую историю!</p><p>Но какую общественную позицию историк займет как ученый, зависит и от его собственного выбора.</p><p>4) История это еще и такой неспокойный предмет исследования, который все время находился и находится в движении, и траекторий движения у него вовсе не одна единственная, а множество. История по определению вариативна. Это заставляет некоторых сомневаться в наличии у истории законов. «Раз невозможно со стопроцентной уверенностью предсказать результат истории, то какая же это тогда наука?», — спрашивает физик или химик. А вот и наука! История это наука об альтернативах исторического процесса развития человечества, наука, призванная дать человечеству знания о себе самом, дабы человечество все-таки научилось управлять практическим процессом своего развития.</p><p>А сие сегодня уже актуальнейшая задача, от решения которой зависят судьбы человечества в самом прямом смысле слова. Истории сегодня необходимо быть наукой.</p><hr><p>2010-05-29 в 10:28</p><p><strong>Forster 2005. Ну, что сказать? По пунктам 1 и 2 — согласна всецело, и вот все пытаюсь понять, что ж мы с коллегами по разные стороны баррикады понимаем под «капитализмом», потому что не может быть в науке десять разных понятий «капитализм». А в понятие (определение) как раз входят его системообразующие признаки, а их-то сформулировал товарищ Маркс...</strong></p><p><strong>По пунктам 3 и 4 — согласна. Только «Раз невозможно со стопроцентной уверенностью предсказать результат истории, то какая же это тогда наука?» (В. Ш.), — спрашивает физик или химик. — нет, мы так не говорим. Наш снобизм, который все же в малых дозах, но присутствует, на другом основан, не на предсказательной возможности гуманитарных наук. Физика на 100% тоже может «предсказать» далеко не все. Вальтраут большое спасибо за ответы!</strong></p><h2 id="о-капитализме-и-об-отчужденном-характере-труда" tabindex="-1"><a class="header-anchor" href="#о-капитализме-и-об-отчужденном-характере-труда"><span>О капитализме и об отчужденном характере труда</span></a></h2><p>2010-05-29 в 10:28</p><p><strong>Forster 2005. Вот все пытаюсь понять, что ж мы с коллегами по разные стороны баррикады понимаем под «капитализмом», потому что не может быть в науке десять разных понятий «капитализм». А в понятие (определение) как раз входят его системообразующие признаки, а их-то сформулировал товарищ Маркс...</strong></p><p><strong>В. Шелике.</strong> Понятия капитализм разводят людей сегодня «по разные стороны баррикад» по многим причинам.</p><p>1) Одна из них отношение людей (наших ученых, политиков, идеологов и граждан) к частной собственности, этой экономической основы капитализма.</p><p>а) Многие люди сегодня склонны воспринимать частную собственность и конкуренцию как священное и неприкосновенное основание, обеспечивающее саморазвитие общества, наконец, достигнутое и Россией, а ранее уже успешно существующее на вызывающем зависть Западе. Для этих людей капитализм (цивилизация, социальное правовое государство, постиндустриальное общество и т. д.) столбовая дорога человечества в светлое будущее (чуток бы подправить, и все окей).</p><p>И Марксовы определения капитализма и его вывод о гибели капитализма в будущем для них чушь собачья, чистейшей воды утопия или злонамеренный обман со стороны очередного «параноика, возомнившего себя Спасителем человечества».</p><p>Они правы только в том, что частная собственность сегодня все еще играет и положительную роль в качестве мотива, стимула для активизации деятельности определенных групп людей, а ее преждевременная отмена и сегодня все еще чревата экономическим застоем (о чем, кстати, писал еще Энгельс!).</p><p>Но и отрицательная роль частной собственности сегодня тоже уже выпирает наружу на каждом углу, особенно в период современного кризиса. И не случайно многим снова стало интересно почитать и «Капитал» Маркса.</p><p>б) Другие люди видят в частной собственности истоки социального неравенства, угнетения, эксплуатации и т. д., и понимают, что частная собственность вовсе не священна и не неприкосновенна, а подлежит «ликвидации». (И впервые такое благородное деяние и совершила, мол, Октябрьская революция). Для них ликвидация частной собственности задача желательной в ближайшем, в самом обозримом, будущем еще одной социальной революции пролетариата в узком смысле, призванной ликвидировать капитализм и обеспечить победу социализма (с человеческим лицом).</p><p>Они правы в том, что видят в частной собственности источник социального неравенства и прочая, и в том, что частная собственность подлежит «ликвидация».</p><p>Но и эта точка зрения теоретически тоже хромает.</p><p>Во первых, правильнее говорить о снятии (Aufhaebung) частной собственности, так у Маркса и Энгельса в «Комманифесте» (а переведено как «ликвидация»). Снятие частной собственности это длительный исторический процесс, который осуществляется в самых разных формах. Ликвидация — одномоментный акт уничтожения частной собственности, что чревато, в конечном счете, застоем, если осуществлен преждевременно.</p><p>Последнее обусловлено тем, что снятие частной собственности требует устранения самого источника возникновения частной собственности, без чего частная собственность будет постоянно самовозрождаться, зачастую в самых уродливых, архаических формах (даже в форме рабства в современную эпоху, например, в ГУЛАГе или в подвале иного частного хозяйства, в тайне от глаз людских в современной России).</p><p>Дело в том, что сама частная собственность порождена отчужденным характера труда, т. е. когда труд сам по себе для человека тяжел, не приносит ему радости, но, чтобы не умереть с голоду, человеку все равно приходится трудиться, (а это уже и определенное насилии, ибо с потребностью в труде люди не рождаются). Естественно, что многие люди сочтут за счастье жить не трудясь, и совсем не случайно в раю, где люди, наконец, счастливы, они ничего не делают! И в истории человечества такая возможность жить, избавляя себя от труда, жить за счет чужого труда, исторически возникает тогда, когда возникает разрыв между работником и условиями его труда (отделение работника от условий его труда). Владение условиями труда дает владельцу возможность жить за счет труда других, чем он реально так или иначе и пользуется в период цивилизации, постепенно вообще избавляя себя от какого-либо участия в трудовом процессе. А трудящемуся остается вечный труд в поте лица своего и мечта о загробном мире.</p><p>Вот отчужденный характер труда в СССР и не был ликвидирован (снят), да и не мог быть ликвидирован (снят). Не тот был уровень хотя бы автоматизации промышленности, да еще и сельское хозяйство требовали от трудящегося уйму тяжелого, нудного, физического труда, т. е. труда, осуществляемого действительно в поте лица своего, как и в прошлом при царизме. В СССР. сохранение отчужденного характера труда не признавалось правительством и официальной идеологией, а, его «ликвидация» провозглашалась громким лозунгом о том, что теперь «Труд дело чести, доблести и геройства».</p><p>Отчужденный характер труда, продолжавший существовать в СССР, приводил к тому, что трудящийся не отказывал себе на работе в долгом перекуре, в халтурном отношении к результатам своего труда, и вообще больше всего на свете любил период своего отпуска (не все, конечно, но многие).</p><p>Сохранение отчужденного характера труда требовало и в СССР методов принуждения к труду, и т. д. что и привело к создания тоталитарного общественного строя (вариант, который Маркс тоже предвидел, когда частная собственность становится государственной и по словам Маркса старая мерзость возрождается в худшем виде).</p><h2 id="о-разном" tabindex="-1"><a class="header-anchor" href="#о-разном"><span>О разном</span></a></h2><p>2010-05-30 в 22:52</p><p><strong>Синяя блуза. А к человечному обществу какой критерий распределения применим? Принцип «от каждого по способностям, каждому по труду», мне кажется, человечный и справедливый. И вполне реальный для жизни. Когда он соблюдается. И когда неукоснительно соблюдается то, что люди, физически неспособные трудиться или много трудиться, должны содержаться обществом. Причем так, чтоб они могли пристойно жить, а не прозябать. Т. е. инвалиды, пенсионеры, временно нетрудоспособные, и т. д.</strong></p><p><strong>В. Шелике.</strong> Распределение по труду Маркс считал принципом распределения, который неизбежен на первом этапе перехода в коммунизму, но оно еще основано на принципах буржуазного права (Критика Готской программы), т. е. не соответствует человечному (коммунистическому) распределению.</p><p>В человечном обществе распределение основано на принципе «От каждого по способностям, каждому про потребностям». (Такой «лозунг» вовсе не утопия. Обратите внимание на то, что именно этот принцип существует в действительности в многих современных семьях, с поправкой на то, что распределения осуществляется в рамках финансовых возможностей той или иной семьи. В семье маленьких детей и взрослых не кормят по принципу «сколько ты заработал, столько и съешь», «вымыл посуду, можешь покушать», хотя за пятерку некоторые родители и дарят детям подарки, по неведению своему).</p><hr><blockquote><p><strong>В. Шелике.</strong> В человечном обществе (коммунизме) единство прогресса и регресса сохраняется? Да или нет?</p></blockquote><p>**<strong>Синяя блуза. Вот интересный вопрос! Вообще, конечно, единство-противоположность прогресса/регресса — это источник тех самых противоречий, без которых нет и развития. Но, может, при коммунизме противоречия будут другого рода? Неантогонистические. И развитие будет не через прогресс/регресс, а через совершенствование?..</strong></p><p><strong>В. Шелике.</strong> Поскольку диалектика открыла возникновение, развитие и исчезновение как закон движения всего на свете, то вряд ли человечное общество сможет обойтись без противоречий прогресса и регресса в своем историческом развитии. Но у прогресса и регресса в человечном обществе иное историческое содержание и проявление. Но и человечное общество (коммунизм) не конечная цель развития человечества (Маркс), а потому тоже чем-то сменится. А чем, ведомо только нашим далеким потомкам, если ближайшие поколения вообще сумеют сохранить жизнь на земле.</p><p><strong>Синяя Блуза: Одно меня удивило, очень сильно:</strong></p><blockquote><p><strong>В. Шелике.</strong> Когда речь идет об уничтожении классов при коммунизме (в человечном обществе), то Маркс имеет в виду не физическое истребление богатых бедными, буржуа пролетарием (как это зачастую понималось, и не только понималось, но и осуществлялось в действительности)...</p></blockquote><p><strong>Никогда не встречал такого толкования, что это «физическое истребление»! И даже не думал, что такое может быть.</strong></p><p><strong>В. Шелике.</strong> А гражданские войны на какой теоретико-психологической основе держатся? А ссылка священников в ГУЛАГ? А Камбоджа? Разве это не физическое истребление «классовых врагов»?</p><p><strong>Синяя Блуза: А можно еще вопрос? Как Вы относитесь к исторической аналогии? Не в публицистике, там все понятно, а как к научному методу? Например, проблема Термидора, который будто бы имеет место в любой революции.</strong></p><p><strong>В. Шелике.</strong> У Маркса есть закон маятника, по которому возникают, достигают апогея и угасают (завершаются) революции в узком смысле (в том числе и ФБР). В этом смысле термидор не аналогия, а по существу закономерность, но разная по форме и по историческому содержанию в разных странах и в разных революциях.</p><hr><p>2010-06-06 в 18:42</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Belle Garde</a>. А кто из социалистов, которых называют утопистами, до Маркса, ближе всех к его теории, как Вы считаете? (Просто задумалась на тему, почему у нас больше всего изучали сенсимонистов, а не Пекера, Видаля, Шарля Фурье, Кабе или других).</strong></p><p><strong>В. Шелике.</strong> Я, к сожалению, не специалист по истории социалистических учений и поэтом не могу ответить на Ваш вопрос.</p><hr><p>2010-06-06 в 22:42</p><p><strong><a href="http://www.diary.ru/~vive-liberta/p107519477.htm" target="_blank" rel="noopener noreferrer">Свой среди чужих...</a>. 1. Говоря о формациях применительно к Западной Европе, какие бы Вы выделили главные признаки (в производстве жизни, и главное — в нематериальном производстве и отношениях): а) для феодализма, б) для капитализма?</strong></p><p><strong>В. Шелике.</strong> У Маркса человеческие отношения к миру есть единство и противоположность материальных и идеальных отношений человечества с миром. В этом ракурсе производство, общение (Verkehr) и общество тоже раздвоены на материальное и духовное производство, на материальное и духовное общение (Verkehr), на гражданское общество и государство (последнее определено Марксом как идеологическое образование, что мало кто понял). Все вместе есть общественная формация.</p><p>А дальше попробуйте сами выделить главные признаки, (а надо бы сущность) феодализма и капитализма, ладно?</p><p><strong>Свой среди чужих. 2. Как Вы считаете, в моменты кризисов в обществе всегда опережающую и главную роль играет общественное сознание?</strong></p><p><strong>В. Шелике.</strong> Я так вообще не считаю. Кризисы (обострения противоречий общественного развития) созревают подспудно, в лучшем случае ощущаемые людьми как какой-то «непорядок в Датском королевстве». А когда кризисы разражаются, все (и власть и граждане) кидаются кто во что горазд понять их истоки или даже сущность. И большинство попадает пальцем в небо, редко кто в самую точку. Какая уж тут опережающая роль общественного сознания?</p><p>Но сегодня человечество как раз дошло до такой степени обострения противоречий своих отношений с миром, что настало самое время понять и осознать законы развития и законы разрушения человечества и мира, т. е. действительно достичь того, чтобы сознание (наука) не только опережало кризисы, но нашло и человечные выходы из них.</p><p>Вы можете сказать, что общественное сознание (в том числе и наука) сегодня с этим уже справились?</p><p><strong>Свой среди чужих. 3. Как Вы объясняете такой, по мнению либералов, «несъедобный» термин — «демократическая диктатура»?</strong></p><p><strong>В. Шелике.</strong> Никак не объясняю. У нас вообще в моде несусветный кавардак понятий и перевертывание их смысла, (не говоря уже об отсутствии хотя бы стремления к научной строгости понятий). Это является очень удобным условием для манипулирования общественным сознанием.</p>',212))])}const b=s(h,[["render",u]]),w=JSON.parse('{"path":"/%D1%88%D0%B5%D0%BB%D0%B8%D0%BA%D0%B5-%D0%B2%D0%BE%D0%BF%D1%80%D0%BE%D1%81%D1%8B-%D0%B8-%D0%BE%D1%82%D0%B2%D0%B5%D1%82%D1%8B-%D0%BE-%D0%BC%D0%B0%D1%80%D0%BA%D1%81%D0%B5-%D0%B8-%D0%BC%D0%B0%D1%80%D0%BA%D1%81%D0%B8%D0%B7%D0%BC%D0%B5.html","title":"Вопросы и ответы: О Марксе и марксизме","lang":"ru","frontmatter":{"format":"comtext","version":"2.0.0","title":"Вопросы и ответы: О Марксе и марксизме","author":["Вальтраут Фрицевна Шелике"],"genre":["sci_history","sci_philosophy"],"date":2010,"lang":"ru"},"git":{},"filePathRelative":"шелике-вопросы-и-ответы-о-марксе-и-марксизме.md"}');export{b as comp,w as data};
